from AlgorithmImports import *
from datetime import datetime, timedelta, time, date


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy_symbol,
            self.consolidator
        )

        self.pending_signal = False
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.blocked_entry_dates = set()

    def OnFiveMinuteBar(self, sender, bar):
        if bar.Symbol != self.spy_symbol:
            return

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if previous_fast is None or previous_slow is None:
            return

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        bar_time = bar.EndTime.time()

        eligible_time = (
            time(9, 45) <= bar_time <= time(14, 30)
        )

        bullish_cross = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if eligible_time and bullish_cross:
            self.pending_signal = True

    def OnData(self, slice):
        today = self.Time.date()

        # Immediately remove unexpected SPY equity positions caused by exercise
        # or assignment.
        spy_quantity = self.Portfolio[self.spy_symbol].Quantity
        if spy_quantity != 0:
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position detected; "
                f"liquidating {spy_quantity} shares."
            )
            self.MarketOrder(self.spy_symbol, -spy_quantity)
            self.blocked_entry_dates.add(today)

        self.ProcessExpirationProtection()
        self.ProcessOptionExit(slice)

        if self.pending_signal:
            self.pending_signal = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        today = self.Time.date()

        if today in self.blocked_entry_dates:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None:
            if self.entry_ticket.Status in (
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.New,
            ):
                return

        chain = None
        for candidate in slice.OptionChains:
            if candidate.Key.Underlying == self.spy_symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped; no option chain.")
            return

        minimum_expiry = today + timedelta(days=7)

        expiries = sorted({
            contract.Symbol.ID.Date.date()
            for contract in chain
            if contract.Symbol.ID.OptionRight == OptionRight.Call
            and contract.Symbol.ID.Date.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug(f"{self.Time}: Entry skipped; no valid expiration.")
            return

        selected_expiry = expiries[0]
        underlying_price = self.Securities[self.spy_symbol].Price

        contracts = [
            contract for contract in chain
            if contract.Symbol.ID.OptionRight == OptionRight.Call
            and contract.Symbol.ID.Date.date() == selected_expiry
        ]

        if not contracts:
            self.Debug(
                f"{self.Time}: Entry skipped; no call contracts at "
                f"{selected_expiry}."
            )
            return

        # Select the nearest-to-the-money call, breaking ties by lower strike.
        selected = min(
            contracts,
            key=lambda contract: (
                abs(contract.Strike - underlying_price),
                contract.Strike
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

    def ProcessOptionExit(self, slice):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        security = self.Securities[self.held_option]
        quote = slice.Bars.get(self.held_option)

        bid = security.BidPrice
        ask = security.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if (
            self.entry_price is not None and
            midpoint >= 1.5 * self.entry_price
        ):
            self.SubmitExit("profit target")

    def ProcessExpirationProtection(self):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        expiry = self.held_option.ID.Date.date()
        today = self.Time.date()

        # Never intentionally carry the option into expiration processing.
        if today >= expiry:
            self.blocked_entry_dates.add(today)
            self.SubmitExit("expiration protection")
            return

        preceding_trading_day = self.PrecedingTradingDay(expiry)

        if (
            today == preceding_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("expiration time stop")

    def PrecedingTradingDay(self, expiry):
        current = expiry - timedelta(days=1)

        while not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(
            current
        ):
            current -= timedelta(days=1)

        return current

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            if self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ):
                return

        self.CancelOpenExitOrder()
        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(
            f"{self.Time}: Exiting {self.held_option.Value}; reason={reason}"
        )

    def CancelOpenExitOrder(self):
        if self.exit_ticket is None:
            return

        if self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            self.exit_ticket.Cancel("Replaced by liquidation order")

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            self.held_option = order_event.Symbol
            self.entry_price = order_event.FillPrice

            self.Debug(
                f"{self.Time}: Entered 1 {self.held_option.Value} call "
                f"at filled price {self.entry_price:.4f}"
            )
            return

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            self.Debug(
                f"{self.Time}: Exit filled for {order_event.Symbol.Value} "
                f"at {order_event.FillPrice:.4f}"
            )

            self.held_option = None
            self.entry_price = None
            self.exit_ticket = None
            self.entry_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            f"{self.Time}: Unexpected option assignment/exercise received."
        )

        self.blocked_entry_dates.add(self.Time.date())

        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity != 0:
            self.MarketOrder(self.spy_symbol, -quantity)

