                    f"{self.Time}: exited {order_event.Symbol.Value} "
                    f"at {order_event.FillPrice:.4f}"
                )
                self.held_option = None
                self.entry_price = None
                self.expiration_date = None

        if self.entry_order is not None and self.entry_order.Status.IsClosed():
            if self.entry_order.Status != OrderStatus.Filled:
                self.entry_order = None

        if self.exit_order is not None and self.exit_order.Status.IsClosed():
            self.exit_order = None

    def OnEndOfAlgorithm(self):
        self.SubscriptionManager.RemoveConsolidator(
            self.spy.Symbol,
            self.consolidator
        )
